              src="${imageSrc}"
              alt="Large landscape artwork with layered mountains under a bright sky"
            />
          </div>
          <div class="preview-meta">
            <div>
              <h2 id="image-title">Blue Summit Campaign Cover</h2>
              <p>
                A polished hero image prepared for the product library and ready for reuse
                across web and mobile surfaces.
              </p>
              <div class="meta-list" aria-label="Image metadata">
                <div class="meta-row"><span>Resolution</span><strong>2400 x 1800</strong></div>
                <div class="meta-row"><span>File type</span><strong>PNG</strong></div>
                <div class="meta-row"><span>Updated</span><strong>Today, 9:42 AM</strong></div>
              </div>
            </div>
            <div class="action-stack">
              <button class="button button-primary" type="button">Share</button>
              <button class="button button-secondary" type="button">Download</button>
              <button
                class="button button-danger trigger"
                type="button"
                data-action="open-dialog"
                aria-haspopup="dialog"
                aria-controls="delete-dialog"
                ${state.isDeleted ? "disabled" : ""}
              >
                Delete image
              </button>
            </div>
          </div>
        </article>
      `;
    }

    function SidePanel() {
      return `
        <aside class="panel side-panel" aria-label="Image insights">
          <div>
            <h2>Publishing notes</h2>
            <p>Keep library content tidy and remove unused images after confirming no live layouts depend on them.</p>
          </div>
          <div class="info-block">
            <span class="info-label">Collection</span>
            <strong>Spring Launch / Hero Assets</strong>
          </div>
          <div class="info-block">
            <span class="info-label">Visibility</span>
            <strong>Internal team workspace</strong>
          </div>
          <div class="info-block">
            <span class="info-label">Owner</span>
            <strong>Brand Design</strong>
          </div>
          <div class="status-banner" ${state.isDeleted ? "" : "hidden"} id="delete-status" role="status" aria-live="polite">
            <strong>Image deleted.</strong>
            <p class="status-text">The asset has been removed from your library.</p>
          </div>
        </aside>
      `;
    }

    function DeleteDialog() {
      return `
        <div
          class="modal-root"
          id="modal-root"
          ${state.isDialogOpen ? "" : "hidden"}
        >
          <div class="modal-backdrop" data-action="close-dialog" aria-hidden="true"></div>
          <section
            class="dialog"
            id="delete-dialog"
            role="dialog"
            aria-modal="true"
            aria-labelledby="dialog-title"
            aria-describedby="dialog-description"
          >
            <div class="dialog-icon" aria-hidden="true">!</div>
            <h2 id="dialog-title">Delete this image?</h2>
            <p id="dialog-description">
