              <button class="button button-ghost" type="button" data-action="close-dialog">Cancel</button>
              <button class="button button-danger" type="button" data-action="confirm-delete">Delete image</button>
            </div>
          </section>
        </div>
      `;
    }

    function render() {
      document.getElementById("app").innerHTML = App();

      if (state.isDialogOpen) {
        const dialog = document.getElementById("delete-dialog");
        const focusables = dialog.querySelectorAll(focusableSelector);
        if (focusables.length > 0) {
          focusables[0].focus();
        }
      }
    }

    function openDialog(trigger) {
      lastTrigger = trigger;
      state.isDialogOpen = true;
      render();
    }

    function closeDialog() {
      state.isDialogOpen = false;
      render();
      if (lastTrigger) {
        lastTrigger.focus();
      }
    }

    function confirmDelete() {
      state.isDeleted = true;
      state.isDialogOpen = false;
      render();
      const status = document.getElementById("delete-status");
      if (status) {
        status.focus?.();
      }
    }

    document.addEventListener("click", (event) => {
      const actionTarget = event.target.closest("[data-action]");
      if (!actionTarget) {
        return;
      }

      const action = actionTarget.getAttribute("data-action");

      if (action === "open-dialog") {
        openDialog(actionTarget);
      }

      if (action === "close-dialog") {
        closeDialog();
      }

      if (action === "confirm-delete") {
        confirmDelete();
      }
    });

    document.addEventListener("keydown", (event) => {
      if (!state.isDialogOpen) {
        return;
      }

      const dialog = document.getElementById("delete-dialog");
      if (!dialog) {
        return;
      }

      if (event.key === "Escape") {
        event.preventDefault();
        closeDialog();
        return;
      }

      if (event.key !== "Tab") {
        return;
      }

      const focusables = Array.from(dialog.querySelectorAll(focusableSelector));
      if (focusables.length === 0) {
        event.preventDefault();
        return;
      }

      const first = focusables[0];
      const last = focusables[focusables.length - 1];

      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    });

    render();
  </script>
