          <linearGradient id="mountain" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stop-color="#1d4ed8" />
            <stop offset="100%" stop-color="#0f172a" />
          </linearGradient>
        </defs>
        <rect width="1200" height="900" fill="url(#sky)" />
        <circle cx="980" cy="170" r="76" fill="#ffffff" opacity="0.75" />
        <path d="M0 700 L240 440 L480 660 L720 380 L960 620 L1200 430 L1200 900 L0 900 Z" fill="url(#mountain)" opacity="0.92" />
        <path d="M0 760 L220 620 L390 710 L600 560 L810 740 L1030 610 L1200 710 L1200 900 L0 900 Z" fill="#1e293b" opacity="0.8" />
        <rect x="120" y="120" width="240" height="150" rx="28" fill="#ffffff" opacity="0.25" />
        <rect x="860" y="520" width="190" height="120" rx="24" fill="#ffffff" opacity="0.2" />
      </svg>
    `);

    const focusableSelector = [
      "button:not([disabled])",
      "[href]",
      "input:not([disabled])",
      "select:not([disabled])",
      "textarea:not([disabled])",
      "[tabindex]:not([tabindex='-1'])"
    ].join(",");

    function App() {
      return `
        <main class="app-shell">
          ${HeroSection()}
          <section class="content-grid" aria-label="Image preview content">
            ${ImagePreviewCard()}
            ${SidePanel()}
          </section>
        </main>
        ${DeleteDialog()}
      `;
    }

    function HeroSection() {
      return `
        <section class="hero">
          <div>
            <span class="eyebrow">Library item preview</span>
            <h1>Review image details before you take action.</h1>
            <p>
              Preview how this asset appears in your library, double-check metadata,
              and remove it only when you're sure you no longer need it.
            </p>
          </div>
          <aside class="metric-card" aria-label="Image statistics">
            <span>Total storage</span>
            <strong>18.4 GB</strong>
            <span>312 items synced across your workspace</span>
          </aside>
        </section>
      `;
    }

    function ImagePreviewCard() {
      return `
        <article class="panel preview-card" aria-labelledby="image-title">
          <div class="preview-image-wrap">
            <img
              class="preview-image"
              src="${imageSrc}"
              alt="Large landscape artwork with layered mountains under a bright sky"
            />
          </div>
          <div class="preview-meta">
            <div>
              <h2 id="image-title">Blue Summit Campaign Cover</h2>
              <p>
                A polished hero image prepared for the product library and ready for reuse
                across web and mobile surfaces.
              </p>
              <div class="meta-list" aria-label="Image metadata">
                <div class="meta-row"><span>Resolution</span><strong>2400 x 1800</strong></div>
                <div class="meta-row"><span>File type</span><strong>PNG</strong></div>
                <div class="meta-row"><span>Updated</span><strong>Today, 9:42 AM</strong></div>
              </div>
            </div>
            <div class="action-stack">
              <button class="button button-primary" type="button">Share</button>
              <button class="button button-secondary" type="button">Download</button>
              <button
                class="button button-danger trigger"
                type="button"
                data-action="open-dialog"
                aria-haspopup="dialog"
                aria-controls="delete-dialog"
                aria-expanded="${state.isDialogOpen ? "true" : "false"}"
                ${state.isDeleted ? "disabled" : ""}
              >
                Delete image
              </button>
            </div>
          </div>
        </article>
      `;
    }

    function SidePanel() {
      return `
        <aside class="panel side-panel" aria-label="Image insights">
          <div>
            <h2>Publishing notes</h2>
            <p>Keep library content tidy and remove unused images after confirming no live layouts depend on them.</p>
          </div>
          <div class="info-block">
            <span class="info-label">Collection</span>
            <strong>Spring Launch / Hero Assets</strong>
          </div>
          <div class="info-block">
            <span class="info-label">Visibility</span>
            <strong>Internal team workspace</strong>
          </div>
          <div class="info-block">
            <span class="info-label">Owner</span>
            <strong>Brand Design</strong>
          </div>
          <div class="status-banner" ${state.isDeleted ? "" : "hidden"} id="delete-status" role="status" aria-live="polite" tabindex="-1">
            <strong>Image deleted.</strong>
            <p class="status-text">The asset has been removed from your library.</p>
          </div>
        </aside>
      `;
    }

    function DeleteDialog() {
      return `
        <div
          class="modal-root"
          id="modal-root"
          ${state.isDialogOpen ? "" : "hidden"}
        >
          <div class="modal-backdrop" data-action="close-dialog" aria-hidden="true"></div>
          <section
            class="dialog"
            id="delete-dialog"
            role="dialog"
            aria-modal="true"
            aria-labelledby="dialog-title"
            aria-describedby="dialog-description"
          >
            <div class="dialog-icon" aria-hidden="true">!</div>
            <h2 id="dialog-title">Delete this image?</h2>
            <p id="dialog-description">
              This will remove the image from your library. You can’t undo this action from this screen.
            </p>
            <div class="dialog-actions">
              <button class="button button-ghost" type="button" data-action="close-dialog">Cancel</button>
              <button class="button button-danger" type="button" data-action="confirm-delete">Delete image</button>
            </div>
          </section>
        </div>
      `;
    }

    function render() {
      document.getElementById("app").innerHTML = App();

      if (state.isDialogOpen) {
        const dialog = document.getElementById("delete-dialog");
        const focusables = dialog.querySelectorAll(focusableSelector);
        if (focusables.length > 0) {
          focusables[0].focus();
        }
      }
    }

    function openDialog() {
      state.isDialogOpen = true;
      render();
    }

    function closeDialog() {
      state.isDialogOpen = false;
      render();
      const trigger = document.querySelector(".trigger:not([disabled])");
      if (trigger) {
        trigger.focus();
      }
    }

    function confirmDelete() {
      state.isDeleted = true;
      state.isDialogOpen = false;
      render();
      const status = document.getElementById("delete-status");
      if (status) {
        status.focus?.();
      }
    }

    document.addEventListener("click", (event) => {
      const actionTarget = event.target.closest("[data-action]");
      if (!actionTarget) {
        return;
      }

      const action = actionTarget.getAttribute("data-action");

      if (action === "open-dialog") {
        openDialog(actionTarget);
      }

      if (action === "close-dialog") {
        closeDialog();
      }

      if (action === "confirm-delete") {
        confirmDelete();
      }
    });

    document.addEventListener("keydown", (event) => {
      if (!state.isDialogOpen) {
        return;
      }

      const dialog = document.getElementById("delete-dialog");
      if (!dialog) {
        return;
      }

      if (event.key === "Escape") {
        event.preventDefault();
        closeDialog();
        return;
      }

      if (event.key !== "Tab") {
        return;
      }

      const focusables = Array.from(dialog.querySelectorAll(focusableSelector));
      if (focusables.length === 0) {
        event.preventDefault();
        return;
      }

      const first = focusables[0];
      const last = focusables[focusables.length - 1];

      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    });

    render();
  </script>
